const claimed=$('Нормализовать runner status').item.json; const response=$input.first().json; const body=response.body??response;
if (Number(response.statusCode??200)!==200) throw new Error('[AGENTIC_RESULT_HTTP_FAILED] runner result request failed');
const envelope=body.validation; const result=body.result;
if (!envelope || envelope.schema_version!=='tender_agent_validation_v1' || envelope.valid!==true) throw new Error('[AGENTIC_VALIDATION_ENVELOPE_INVALID] validation envelope is not valid');
if (String(body.job_id??'')!==claimed.job_id || String(envelope.job_id??'')!==claimed.job_id) throw new Error('[AGENTIC_RESULT_IDENTITY_MISMATCH] job_id');
if (!result || result.schema_version!=='tender_agent_result_v1') throw new Error('[AGENTIC_RESULT_CONTRACT_INVALID] result schema');
if (result.field_catalog_version!==claimed.field_catalog_version || result.field_catalog_sha256!==claimed.field_catalog_sha256) throw new Error('[AGENTIC_RESULT_IDENTITY_MISMATCH] field catalog');
if (result.input_manifest_sha256!==claimed.input_manifest_sha256) throw new Error('[AGENTIC_RESULT_IDENTITY_MISMATCH] input manifest');
if (!/^[0-9a-f]{64}$/iu.test(String(envelope.raw_result_sha256??'')) || !/^[0-9a-f]{64}$/iu.test(String(envelope.validated_result_sha256??''))) throw new Error('[AGENTIC_RESULT_HASH_INVALID] result hashes');
if (!Array.isArray(envelope.fields) || envelope.fields.length !== 27 || !Array.isArray(result.fields) || result.fields.length !== 27) throw new Error('[AGENTIC_RESULT_FIELD_SET_MISMATCH] fields.length !== 27');
const fields=result.fields.map((field,index)=>{
 const validation=envelope.fields[index];
 if (validation.field_index!==field.field_index || validation.field_key!==field.field_key || validation.status!==field.status || validation.value_text!==field.value_text) throw new Error('[AGENTIC_RESULT_FIELD_IDENTITY_MISMATCH] validation field');
 return {...field,issues:validation.issues,result_json:field};
});
return [{json:{...claimed,raw_result_sha256:envelope.raw_result_sha256,validated_result_sha256:envelope.validated_result_sha256,
fields,validation_summary:{valid:true,raw_result_sha256:envelope.raw_result_sha256,validated_result_sha256:envelope.validated_result_sha256,job_issue_codes:(envelope.job_issues??[]).slice(0,100).map(issue=>String(issue.code??'SCHEMA_INVALID').slice(0,80))},
artifacts:{raw_result_sha256:envelope.raw_result_sha256,validated_result_sha256:envelope.validated_result_sha256}}}];

